/* Rules view — the UPS rulebook, written for owners.
 *
 * Two layers, both generated by scripts/build_rulebook_data.py:
 *   topics   — canon reorganized into what owners look up ("Starting Lineups"),
 *              in the present tense. This is what the view leads with.
 *   sections — canon verbatim, kept underneath each topic in a drawer so anyone
 *              who wants to litigate the exact wording still can.
 *
 * The first version of this screen mirrored canon's own structure (Player
 * Lifecycle -> Transaction Catalog -> rule ids -> "see T2.4"). That is an
 * archive, not a rulebook: it answered "where does this rule live" when the
 * owner was asking "what is the rule". Hence topics.
 *
 * Nothing here restates a rule. Canon changes -> CI rebuilds -> this updates.
 * The payload ships as .js because sw.js caches .js cache-first, which is what
 * makes the rulebook readable with no signal.
 */
(function () {
  "use strict";
  if (!window.UPS_MOBILE) return;
  var M = window.UPS_MOBILE;
  var U = M.util;

  var DATA_URL = "./data/rules_data.js";
  var state = {
    q: "",
    topic: null,        // open topic key, or null for the index
    pane: "book",       // book | changes
    openDrawer: {},
    openChange: {},
    showInternal: false,
    index: null,
    pendingAnchor: null
  };

  // ---------------------------------------------------------------- data

  function ensureData(cb) {
    if (window.UPS_RULES_DATA) { cb(null, window.UPS_RULES_DATA); return; }
    var s = document.createElement("script");
    s.src = DATA_URL + "?v=" + encodeURIComponent(M.BUILD || "1");
    s.async = true;
    s.onload = function () {
      if (window.UPS_RULES_DATA) cb(null, window.UPS_RULES_DATA);
      else cb(new Error("rules data loaded but empty"));
    };
    s.onerror = function () { cb(new Error("could not load the rulebook")); };
    document.head.appendChild(s);
  }

  function stripTags(html) { return String(html || "").replace(/<[^>]+>/g, " "); }

  // anchor -> canon rule, built once. Topics cite rules by anchor; the blocks
  // live in `sections`, so nothing is shipped twice.
  var byAnchor = null;
  function ruleAt(data, anchor) {
    if (!byAnchor) {
      byAnchor = {};
      (data.sections || []).forEach(function (sec) {
        (sec.groups || []).forEach(function (grp) {
          (grp.rules || []).forEach(function (r) {
            byAnchor[r.anchor] = r;
            (r.children || []).forEach(function (c) { byAnchor[c.anchor] = c; });
          });
        });
      });
    }
    return byAnchor[anchor] || null;
  }

  // A canon list can mix owner rules with commish scaffolding ("Implementation
  // ownership…" inside B2 Taxi Squad). `has_int` marks those; the internal
  // <li>s are REMOVED from the fragment rather than hidden with CSS, so a
  // member's page genuinely does not contain them.
  function blockHtml(b) {
    if (!b.has_int || state.showInternal) return b.html;
    var box = document.createElement("div");
    box.innerHTML = b.html;
    var ints = box.querySelectorAll(".ups-m-rb-int");
    for (var i = ints.length - 1; i >= 0; i--) {
      if (ints[i].parentNode) ints[i].parentNode.removeChild(ints[i]);
    }
    return box.innerHTML;
  }

  function esc(v) { return U.escapeHtml(v == null ? "" : v); }

  // ---------------------------------------------------------------- search

  // Search covers the owner-facing topics AND canon, so a member can type
  // either what they call it ("cut penalty") or what canon calls it ("D1").
  function buildIndex(data) {
    var rows = [];
    (data.topics || []).forEach(function (t) {
      var parts = [t.title, t.one_liner]
        .concat(t.today || [])
        .concat((t.numbers || []).map(function (n) { return n.label + " " + n.value; }))
        .concat(t.gotchas || [])
        .concat((t.examples || []).map(function (e) {
          return e.title + " " + (e.lines || []).join(" ");
        }))
        .concat((t.table && t.table.rows || []).map(function (r) { return r.join(" "); }))
        .concat((t.timeline || []).map(function (e) {
          return e.when + " " + e.what + " " + (e.detail || "");
        }));
      rows.push({
        kind: "topic", topic: t,
        title: t.title,
        hay: parts.join(" ").toLowerCase(),
        blurb: t.one_liner
      });
    });
    (data.sections || []).forEach(function (sec) {
      (sec.groups || []).forEach(function (grp) {
        (grp.rules || []).forEach(function (r) {
          if (r.internal && !state.showInternal) return;
          var body = (r.blocks || [])
            .filter(function (b) { return !b.internal; })
            .map(function (b) { return stripTags(b.html); }).join(" ");
          rows.push({
            kind: "canon", rule: r, sec: sec,
            title: r.title,
            hay: ((r.id ? r.id + " " : "") + r.title + " " + body).toLowerCase(),
            blurb: body.replace(/\s+/g, " ").trim().slice(0, 150)
          });
        });
      });
    });
    return rows;
  }

  function search(rows, q) {
    var terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    if (!terms.length) return [];
    var out = [];
    for (var i = 0; i < rows.length; i++) {
      var row = rows[i], score = 0, ok = true;
      for (var t = 0; t < terms.length; t++) {
        var term = terms[t];
        var inTitle = row.title.toLowerCase().indexOf(term) !== -1;
        var inBody = row.hay.indexOf(term) !== -1;
        if (!inTitle && !inBody) { ok = false; break; }
        if (inTitle) score += 40;
        if (inBody) score += 5;
      }
      // A topic is the answer; a canon rule is the citation behind it.
      if (ok) out.push({ row: row, score: score + (row.kind === "topic" ? 50 : 0) });
    }
    out.sort(function (a, b) { return b.score - a.score; });
    return out;
  }

  function snippet(row, q) {
    var terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    var text = row.blurb || "";
    var html = esc(text);
    terms.forEach(function (t) {
      if (!t) return;
      var re = new RegExp("(" + t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "ig");
      html = html.replace(re, "<mark>$1</mark>");
    });
    return html;
  }

  // ---------------------------------------------------------------- pieces

  function numbersGrid(nums) {
    if (!nums || !nums.length) return "";
    return '<div class="ups-m-rb-facts">' + nums.map(function (n) {
      return '<div class="ups-m-rb-fact">' +
        '<div class="ups-m-rb-fact-v">' + esc(n.value) + "</div>" +
        '<div class="ups-m-rb-fact-l">' + esc(n.label) + "</div>" +
      "</div>";
    }).join("") + "</div>";
  }

  function tableBlock(tbl) {
    if (!tbl || !tbl.head) return "";
    return '<div class="ups-m-rb-tablewrap"><table class="ups-m-rb-table"><thead><tr>' +
      tbl.head.map(function (h) { return "<th>" + esc(h) + "</th>"; }).join("") +
      "</tr></thead><tbody>" +
      (tbl.rows || []).map(function (r) {
        return "<tr>" + r.map(function (c) { return "<td>" + esc(c) + "</td>"; }).join("") + "</tr>";
      }).join("") +
      "</tbody></table></div>" +
      (tbl.caption ? '<div class="ups-m-rb-cap">' + esc(tbl.caption) + "</div>" : "");
  }

  function examplesBlock(examples) {
    if (!examples || !examples.length) return "";
    return '<div class="ups-m-rb-sub-h">Worked examples</div>' +
      examples.map(function (e) {
        return '<div class="ups-m-rb-ex">' +
          '<div class="ups-m-rb-ex-t">' + esc(e.title) + "</div>" +
          '<ol class="ups-m-rb-ex-l">' +
            (e.lines || []).map(function (l) { return "<li>" + esc(l) + "</li>"; }).join("") +
          "</ol>" +
        "</div>";
      }).join("");
  }

  function timelineBlock(items) {
    if (!items || !items.length) return "";
    return '<div class="ups-m-rb-time">' + items.map(function (e) {
      return '<div class="ups-m-rb-tl">' +
        '<div class="ups-m-rb-tl-when">' + esc(e.when) +
          (e.approx ? ' <span class="ups-m-rb-approx" title="Date not yet confirmed">approx</span>' : "") +
        "</div>" +
        '<div class="ups-m-rb-tl-body">' +
          '<div class="ups-m-rb-tl-what">' + esc(e.what) + "</div>" +
          (e.detail ? '<div class="ups-m-rb-tl-d">' + esc(e.detail) + "</div>" : "") +
        "</div>" +
      "</div>";
    }).join("") + "</div>";
  }

  function canonDrawer(topic, data) {
    var cites = topic.cites || [];
    if (!cites.length) return "";
    var open = !!state.openDrawer[topic.key];
    var h = '<div class="ups-m-rb-drawer' + (open ? " is-open" : "") + '">' +
      '<button class="ups-m-rb-drawer-btn" data-rb-drawer="' + esc(topic.key) + '" aria-expanded="' + (open ? "true" : "false") + '">' +
        "The exact wording in the rulebook" +
        '<span class="ups-m-rb-caret" aria-hidden="true">›</span>' +
      "</button>";
    if (open) {
      h += '<div class="ups-m-rb-drawer-body">';
      cites.forEach(function (c) {
        h += '<div class="ups-m-rb-cite" id="rb-' + esc(c.anchor) + '">' +
          '<div class="ups-m-rb-cite-h">' +
            '<span class="ups-m-rb-rid">' + esc(c.id) + "</span>" +
            '<span class="ups-m-rb-cite-t">' + esc(c.title) + "</span>" +
            '<span class="ups-m-rb-cite-s">§' + esc(c.section) + "</span>" +
          "</div>" +
          ((ruleAt(data, c.anchor) || {}).blocks || [])
            .filter(function (b) { return !b.internal || state.showInternal; })
            .map(function (b) { return blockHtml(b); }).join("") +
        "</div>";
      });
      h += "</div>";
    }
    return h + "</div>";
  }

  // ---------------------------------------------------------------- panes

  // The ten questions that get asked mid-argument, straight to the topic that
  // answers them. Cheaper than scrolling the index for the common cases.
  function renderQuick(data) {
    var quick = (data.quick || []).filter(function (q) { return q.topic; });
    if (!quick.length) return "";
    return '<div class="ups-m-rb-quickwrap"><div class="ups-m-rb-quick">' +
      quick.map(function (q) {
        return '<button class="ups-m-rb-qbtn" data-rb-topic="' + esc(q.topic) + '">' +
          esc(q.q) + "</button>";
      }).join("") + "</div></div>";
  }

  function topicRow(t) {
    return '<button class="ups-m-rb-topic" data-rb-topic="' + esc(t.key) + '">' +
      '<span class="ups-m-rb-topic-t">' + esc(t.title) + "</span>" +
      '<span class="ups-m-rb-caret" aria-hidden="true">›</span>' +
    "</button>";
  }

  function renderIndex(data) {
    var topics = data.topics || [];
    if (!topics.length) {
      return '<div class="ups-m-rb-empty">The rulebook is still being written. ' +
        'Search below to read the rulebook directly.</div>';
    }
    var quick = renderQuick(data);
    var groups = data.groups || [];

    // No groups defined (or an older payload) — fall back to the flat list so
    // the tab still renders rather than coming up empty.
    if (!groups.length) {
      return quick + '<div class="ups-m-rb-topics">' +
        topics.map(topicRow).join("") + "</div>";
    }

    var h = quick;
    groups.forEach(function (g) {
      var mine = topics.filter(function (t) { return t.group === g.key; });
      if (!mine.length) return;
      h += '<div class="ups-m-rb-group">' +
        '<div class="ups-m-rb-group-h">' + esc(g.title) +
          (g.blurb ? '<span class="ups-m-rb-group-b">' + esc(g.blurb) + "</span>" : "") +
        "</div>" +
        '<div class="ups-m-rb-topics">' + mine.map(topicRow).join("") + "</div>" +
      "</div>";
    });

    // Anything whose group was dropped from the payload still needs a home.
    var known = {};
    groups.forEach(function (g) { known[g.key] = 1; });
    var orphans = topics.filter(function (t) { return !t.group || !known[t.group]; });
    if (orphans.length) {
      h += '<div class="ups-m-rb-group">' +
        '<div class="ups-m-rb-group-h">More</div>' +
        '<div class="ups-m-rb-topics">' + orphans.map(topicRow).join("") + "</div>" +
      "</div>";
    }
    return h;
  }

  function renderTopic(data, key) {
    var t = (data.topics || []).filter(function (x) { return x.key === key; })[0];
    if (!t) return renderIndex(data);

    var h = '<button class="ups-m-rb-back" data-rb-topic="">‹ All topics</button>' +
      '<div class="ups-m-rb-topic-head">' +
        "<h2>" + esc(t.title) + "</h2>" +
        '<p class="ups-m-rb-lede">' + esc(t.one_liner) + "</p>" +
      "</div>";

    // Honesty marker: this topic states a rule canon does not yet carry.
    if (t.needs_canon) {
      h += '<div class="ups-m-rb-nocanon"><b>Not in the rulebook yet.</b> ' +
        esc(t.needs_canon) + "</div>";
    }

    // Each topic decides its own block order. This used to be a hardcoded
    // sequence, which is why every page looked identical whether or not the
    // blocks earned their place — a table topic and a prose topic came out the
    // same shape. `layout` lets the content lead; DEFAULT_LAYOUT is the
    // fallback for any topic that hasn't been given one.
    var BLOCKS = {
      numbers: function () { return numbersGrid(t.numbers); },
      today: function () {
        if (!t.today || !t.today.length) return "";
        return '<div class="ups-m-rb-today">' +
          t.today.map(function (p) { return "<p>" + esc(p) + "</p>"; }).join("") +
          "</div>";
      },
      timeline: function () { return timelineBlock(t.timeline); },
      table: function () { return tableBlock(t.table); },
      examples: function () { return examplesBlock(t.examples); },
      gotchas: function () {
        if (!t.gotchas || !t.gotchas.length) return "";
        return '<div class="ups-m-rb-sub-h">Details</div>' +
          '<ul class="ups-m-rb-gotchas">' +
          t.gotchas.map(function (g) { return "<li>" + esc(g) + "</li>"; }).join("") +
          "</ul>";
      },
      open_questions: function () {
        if (!t.open_questions || !t.open_questions.length) return "";
        return '<div class="ups-m-rb-open">' +
          '<div class="ups-m-rb-open-h">Open questions</div>' +
          "<ul>" + t.open_questions.map(function (q) { return "<li>" + esc(q) + "</li>"; }).join("") +
          "</ul></div>";
      },
      era_notes: function () {
        if (!t.era_notes || !t.era_notes.length) return "";
        return '<div class="ups-m-rb-eras">' +
          t.era_notes.map(function (e) {
            return '<span class="ups-m-rb-era">' + esc(e) + "</span>";
          }).join("") + "</div>";
      }
    };
    var DEFAULT_LAYOUT = ["numbers", "today", "timeline", "table", "examples",
                          "gotchas", "open_questions", "era_notes"];
    var layout = (t.layout && t.layout.length) ? t.layout : DEFAULT_LAYOUT;
    layout.forEach(function (name) {
      var fn = BLOCKS[name];
      if (fn) h += fn();
    });

    h += canonDrawer(t, data);
    h += '<button class="ups-m-rb-copy" data-rb-copy="' + esc(t.key) + '">Copy link to ' + esc(t.title) + "</button>";
    return h;
  }

  function renderResults(data) {
    var hits = search(state.index, state.q);
    var h = '<div class="ups-m-rb-resultcount">' + hits.length +
      (hits.length === 1 ? " result" : " results") + ' for "' + esc(state.q) + '"</div>';
    if (!hits.length) {
      h += '<div class="ups-m-rb-empty">Nothing matched. Try a shorter word — ' +
        '<button class="ups-m-rb-link" data-rb-try="taxi">taxi</button>, ' +
        '<button class="ups-m-rb-link" data-rb-try="cut">cut</button>, or ' +
        '<button class="ups-m-rb-link" data-rb-try="trade">trade</button>.</div>';
      return h;
    }
    hits.slice(0, 40).forEach(function (hit) {
      var r = hit.row;
      if (r.kind === "topic") {
        h += '<button class="ups-m-rb-hit ups-m-rb-hit-topic" data-rb-topic="' + esc(r.topic.key) + '">' +
          '<span class="ups-m-rb-hit-k">Topic</span>' +
          '<span class="ups-m-rb-hit-t">' + esc(r.title) + "</span>" +
          '<span class="ups-m-rb-hit-b">' + snippet(r, state.q) + "</span>" +
        "</button>";
      } else {
        h += '<div class="ups-m-rb-hit">' +
          '<span class="ups-m-rb-hit-k ups-m-rb-hit-canon">Rulebook' +
            (r.rule.id ? " · " + esc(r.rule.id) : "") + "</span>" +
          '<span class="ups-m-rb-hit-t">' + esc(r.title) + "</span>" +
          '<span class="ups-m-rb-hit-b">' + snippet(r, state.q) + "</span>" +
        "</div>";
      }
    });
    return h;
  }

  function renderChanges(data) {
    var h = '<div class="ups-m-rb-note">Every rule change since the bot started tracking, ' +
      "newest first. When a proposal passes its vote, the rulebook is updated and this page " +
      "follows automatically.</div>";
    var log = data.changelog || [];
    if (!log.length) return h + '<div class="ups-m-rb-empty">No recorded changes yet.</div>';
    log.forEach(function (e, i) {
      var k = "chg-" + i;
      var open = !!state.openChange[k];
      var cls = e.result === "PASSED" ? "ok" : (e.result === "REJECTED" ? "no" : "adopt");
      h += '<div class="ups-m-rb-chg' + (open ? " is-open" : "") + '">' +
        '<button class="ups-m-rb-chg-h" data-rb-change="' + k + '" aria-expanded="' + (open ? "true" : "false") + '">' +
          '<span class="ups-m-rb-chgdate">' + esc(e.date) + "</span>" +
          '<span class="ups-m-rb-hit-t">' + esc(e.title) + "</span>" +
          '<span class="ups-m-rb-caret" aria-hidden="true">›</span>' +
        "</button>" +
        '<div class="ups-m-rb-meta">' +
          '<span class="ups-m-rb-badge ups-m-rb-badge-' + cls + '">' + esc(e.result) +
            (e.tally ? " " + esc(e.tally) : "") + "</span>" +
        "</div>";
      if (open) {
        h += '<div class="ups-m-rb-body">' +
          (e.proposal || []).map(function (b) { return b.html; }).join("") +
          (e.thread ? '<a class="ups-m-rb-thread" href="' + esc(e.thread) +
            '" target="_blank" rel="noopener noreferrer">Open the Discord thread</a>' : "") +
        "</div>";
      }
      h += "</div>";
    });
    return h;
  }

  // ---------------------------------------------------------------- shell

  function paint(mount, data) {
    var body;
    if (state.q) body = renderResults(data);
    else if (state.pane === "changes") body = renderChanges(data);
    else if (state.topic) body = renderTopic(data, state.topic);
    else body = renderIndex(data);

    var el = mount.querySelector("#ups-m-rb-body");
    if (el) el.innerHTML = body;
    var clear = mount.querySelector("#ups-m-rb-clear");
    if (clear) clear.style.display = state.q ? "" : "none";
    var tabs = mount.querySelectorAll("[data-rb-pane]");
    for (var j = 0; j < tabs.length; j++) {
      tabs[j].classList.toggle("is-on", tabs[j].getAttribute("data-rb-pane") === state.pane);
    }
    var main = document.getElementById("ups-m-main");
    if (main && main.scrollTo) main.scrollTo({ top: 0 });
  }

  function shell(data) {
    var stamp = "Rulebook " + esc(data.version) +
      (data.last_changed ? " · last rule change " + esc(data.last_changed) : "");
    return '' +
      '<div class="ups-m-rb-wrap">' +
        '<div class="ups-m-rb-head">' +
          '<div class="ups-m-rb-stamp">' + stamp + "</div>" +
          '<div class="ups-m-rb-tabs">' +
            '<button class="ups-m-rb-tab is-on" data-rb-pane="book">Rulebook</button>' +
            '<button class="ups-m-rb-tab" data-rb-pane="changes">What\'s changed</button>' +
          "</div>" +
        "</div>" +
        '<div class="ups-m-rb-searchbar">' +
          '<input id="ups-m-rb-search" class="ups-m-rb-input" type="search" ' +
            'placeholder="Search — cut penalty, taxi, trade deadline…" ' +
            'autocomplete="off" autocorrect="off" spellcheck="false" enterkeyhint="search" />' +
          '<button id="ups-m-rb-clear" class="ups-m-rb-clear" style="display:none" aria-label="Clear search">✕</button>' +
        "</div>" +
        '<div id="ups-m-rb-body"></div>' +
        '<div class="ups-m-rb-foot">' +
          "<div>Generated from <code>" + esc(data.canon_path) + "</code>" +
            (data.canon_digest ? " · build " + esc(data.canon_digest) : "") + "</div>" +
          '<div class="ups-m-rb-footrow">' +
            (M.state && M.state.isCommish
              ? '<button id="ups-m-rb-internal" class="ups-m-rb-link">Show commish notes</button>'
              : "") +
          "</div>" +
        "</div>" +
      "</div>";
  }

  function wire(mount, data) {
    var input = mount.querySelector("#ups-m-rb-search");
    var timer = null;

    mount.addEventListener("input", function (e) {
      if (!e.target || e.target.id !== "ups-m-rb-search") return;
      clearTimeout(timer);
      var v = e.target.value;
      timer = setTimeout(function () {
        state.q = v.trim();
        paint(mount, data);
      }, 120);
    });

    mount.addEventListener("click", function (e) {
      var t = e.target;
      var hit = function (attr) {
        var n = t.closest ? t.closest("[" + attr + "]") : null;
        return n ? n.getAttribute(attr) : null;
      };

      var topic = hit("data-rb-topic");
      if (topic !== null) {
        state.topic = topic || null;
        state.q = "";
        if (input) input.value = "";
        paint(mount, data);
        return;
      }

      var drawer = hit("data-rb-drawer");
      if (drawer) {
        state.openDrawer[drawer] = !state.openDrawer[drawer];
        paint(mount, data);
        return;
      }

      var change = hit("data-rb-change");
      if (change) {
        state.openChange[change] = !state.openChange[change];
        paint(mount, data);
        return;
      }

      var pane = hit("data-rb-pane");
      if (pane) {
        state.pane = pane;
        state.q = "";
        state.topic = null;
        if (input) input.value = "";
        paint(mount, data);
        return;
      }

      var tryTerm = hit("data-rb-try");
      if (tryTerm) {
        state.q = tryTerm;
        if (input) input.value = tryTerm;
        paint(mount, data);
        return;
      }

      var copy = hit("data-rb-copy");
      if (copy) {
        var url = location.origin + location.pathname + "#more/rules/" + copy;
        var done = function () { if (M.ui.showToast) M.ui.showToast("Link copied", "ok"); };
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(url).then(done, function () {
            window.prompt("Copy this link:", url);
          });
        } else {
          window.prompt("Copy this link:", url);
        }
        return;
      }

      if (t.id === "ups-m-rb-clear") {
        state.q = "";
        if (input) { input.value = ""; input.focus(); }
        paint(mount, data);
        return;
      }

      if (t.id === "ups-m-rb-internal") {
        state.showInternal = !state.showInternal;
        t.classList.toggle("is-on", state.showInternal);
        t.textContent = state.showInternal ? "Hide commish notes" : "Show commish notes";
        state.index = buildIndex(data);
        paint(mount, data);
        return;
      }
    });
  }

  function render(mount, anchor) {
    mount.innerHTML = '<div class="ups-m-rb-wrap"><div class="ups-m-rb-loading">Loading the rulebook…</div></div>';
    ensureData(function (err, data) {
      if (err) {
        mount.innerHTML = '<div class="ups-m-rb-wrap"><div class="ups-m-rb-empty">' +
          esc(err.message) + " — it'll be here once you're back online.</div></div>";
        return;
      }
      state.index = state.index || buildIndex(data);
      var target = anchor || state.pendingAnchor;
      state.pendingAnchor = null;
      // A deep link names a topic; older links named a canon anchor, so fall
      // back to whichever topic cites that rule.
      if (target) {
        var known = (data.topics || []).some(function (t) { return t.key === target; });
        if (known) {
          state.topic = target;
        } else {
          (data.topics || []).forEach(function (t) {
            (t.cites || []).forEach(function (c) {
              if (!state.topic && (c.anchor === target || c.id === target)) {
                state.topic = t.key;
                state.openDrawer[t.key] = true;
              }
            });
          });
        }
      }
      mount.innerHTML = shell(data);
      wire(mount, data);
      paint(mount, data);
    });
  }

  M.rulesView = {
    render: render,
    openAt: function (a) { state.pendingAnchor = a; }
  };
})();
